mkdir -p <TMP>/shots && cat > <TMP>/shots/shot.mjs <<'EOF'
import { createRequire } from 'module';
const require = createRequire('<HOME>/.local/lib/node_modules/@playwright/mcp/node_modules/');
const { chromium } = require('playwright-core');
const b = await chromium.launch({ executablePath: process.env.HOME + '/.cache/ms-playwright/chromium-1223/chrome-linux/chrome', args: ['--no-sandbox','--use-gl=swiftshader'] });
const errs = [];
async function run(name, vp, opts = {}) {
  const p = await b.newPage({ viewport: vp, deviceScaleFactor: 1, reducedMotion: opts.reduced ? 'reduce' : 'no-preference' });
  p.on('pageerror', e => errs.push(name + ': ' + e.message));
  p.on('console', m => { if (m.type() === 'error') errs.push(name + ': ' + m.text()); });
  await p.goto('file://<WORKSPACE>/anthropic/opus-5.5/medium/index.html');
  await p.waitForTimeout(1500);
  if (opts.mouse) { for (let i = 0; i < 12; i++) { await p.mouse.move(vp.width*0.35 + i*20, vp.height*0.58 + Math.sin(i)*8); await p.waitForTimeout(40); } await p.waitForTimeout(300); }
  await p.screenshot({ path: `<TMP>/shots/${name}.png` });
  await p.close();
}
await run('desk', { width: 1440, height: 900 });
await run('mouse', { width: 1440, height: 900 }, { mouse: true });
await run('phone', { width: 390, height: 844 });
await run('reduced', { width: 1280, height: 800 }, { reduced: true });
console.log(errs.join('\n') || 'no errors');
await b.close();
EOF
node <TMP>/shots/shot.mjs
